		{
			in: VulnInfo{
				CveContents: CveContents{
					Ubuntu: []CveContent{{
						Type:          Ubuntu,
						Cvss3Severity: "HIGH",
					}},
				},
			},
			out: []CveContentCvss{
				{
					Type: Ubuntu,
					Value: Cvss{
						Type:                 CVSS3,
						Score:                8.9,
						CalculatedBySeverity: true,
						Severity:             "HIGH",
					},
				},
			},
		},
		// Empty
		{
			in:  VulnInfo{},
			out: nil,
		},
	}
	for i, tt := range tests {
